// Monday to Monday of last week in your timezone. Every source is read for this window.
const cfg = $('Config').first().json;
const start = DateTime.now().setZone(cfg.timezone).startOf('week').minus({ weeks: 1 }), end = start.plus({ weeks: 1 });
return [{ json: { week: start.toISODate(), start_iso: start.toUTC().toISO(), end_iso: end.toUTC().toISO(), start_date: start.toISODate(),
  end_date: end.minus({ days: 1 }).toISODate(), start_ms: start.toMillis(), end_ms: end.toMillis(), today: DateTime.now().setZone(cfg.timezone).toISODate() } }];

// What the three sources return for one week, so "Test workflow" shows the sheet row and the email without any accounts.
const deal = (amt, stage) => ({ properties: { amount: String(amt), dealstage: stage } });
return [{ json: { sample: true,
  hs_created: { total: 14, results: [deal(4000, 'appointmentscheduled'), deal(2500, 'qualifiedtobuy'), deal(9000, 'appointmentscheduled')] },
  hs_won: { total: 3, results: [deal(5200, 'closedwon'), deal(1800, 'closedwon'), deal(7400, 'closedwon')] },
  hs_open: { total: 22, results: [deal(4000, 'appointmentscheduled'), deal(12500, 'presentationscheduled'), deal(9000, 'contractsent')] },
  qb_invoices: { QueryResponse: { Invoice: [{ TotalAmt: 4200, Balance: 0 }, { TotalAmt: 1350, Balance: 1350 }, { TotalAmt: 8800, Balance: 2000 }] } },
  qb_payments: { QueryResponse: { Payment: [{ TotalAmt: 6100 }, { TotalAmt: 950 }] } },
  qb_open: { QueryResponse: { Invoice: [{ Balance: 1350, DueDate: '2099-01-01' }, { Balance: 2000, DueDate: '2000-01-01' }, { Balance: 640, DueDate: '2000-01-01' }] } },
  stripe: [{ amount: 12000, amount_refunded: 0, status: 'succeeded', paid: true }, { amount: 4900, amount_refunded: 4900, status: 'succeeded', paid: true },
           { amount: 2900, amount_refunded: 0, status: 'failed', paid: false }, { amount: 9900, amount_refunded: 0, status: 'succeeded', paid: true }] } }];

// One row of numbers for the week. A source that is switched off shows blank; one that failed shows blank and is named in the email.
const cfg = $('Config').first().json, wk = $('Last week').first().json;
const S = $('Sample data').isExecuted ? $('Sample data').first().json : null;
const pages = n => S ? null : ($(n).isExecuted ? $(n).all().map(i => i.json) : null);   // HTTP pagination returns one item per page
const failed = [];
const take = (n, sampleKey) => {
  if (S) return S[sampleKey] === undefined ? null : [].concat(S[sampleKey]);
  const p = pages(n); if (!p) return null;
  const bad = p.find(x => x.error); if (bad) { failed.push(`${n}: ${String(bad.error.message || bad.error).slice(0, 160)}`); return null; }
  return p;
};
const money = x => Math.round(x * 100) / 100, amt = r => Number((r.properties || {}).amount || 0);
const row = { week: wk.week };
const hc = take('Deals created', 'hs_created'), hw = take('Deals won', 'hs_won'), ho = take('Open deals', 'hs_open');
const hsSum = p => money(p.flatMap(x => x.results || []).reduce((s, r) => s + amt(r), 0));
const hsCount = p => p[0].total ?? p.flatMap(x => x.results || []).length;
Object.assign(row, { deals_created: hc ? hsCount(hc) : '', deals_created_value: hc ? hsSum(hc) : '', deals_won: hw ? hsCount(hw) : '',
  deals_won_value: hw ? hsSum(hw) : '', open_pipeline: ho ? hsSum(ho) : '' });
const qi = take('Invoices sent', 'qb_invoices'), qp = take('Payments received', 'qb_payments'), qo = take('Unpaid invoices', 'qb_open');
const qrows = (p, k) => p.flatMap(x => (x.QueryResponse || {})[k] || []);
Object.assign(row, { invoiced: qi ? money(qrows(qi, 'Invoice').reduce((s, r) => s + Number(r.TotalAmt), 0)) : '',
  payments_received: qp ? money(qrows(qp, 'Payment').reduce((s, r) => s + Number(r.TotalAmt), 0)) : '',
  unpaid: qo ? money(qrows(qo, 'Invoice').reduce((s, r) => s + Number(r.Balance), 0)) : '',
  overdue: qo ? money(qrows(qo, 'Invoice').filter(r => r.DueDate && r.DueDate < wk.today).reduce((s, r) => s + Number(r.Balance), 0)) : '' });
const sc = take('Stripe charges', 'stripe');
const ch = sc ? (S ? sc : sc.flatMap(x => x.data || [])).filter(c => !c.currency || c.currency === cfg.currency) : null;
Object.assign(row, { card_payments: ch ? money(ch.filter(c => c.paid).reduce((s, c) => s + (c.amount - c.amount_refunded) / 100, 0)) : '',
  refunds: ch ? money(ch.reduce((s, c) => s + c.amount_refunded / 100, 0)) : '', failed_payments: ch ? ch.filter(c => c.status === 'failed').length : '' });
return [{ json: { row, failed } }];

// Finds last week's row in the sheet (if any) and works out the change for each number. Re-running a week replaces its row.
const { row, failed } = $('Work out the numbers').first().json;
const rows = $('Read earlier weeks').all().map(i => i.json).filter(r => r.week && r.week < row.week).sort((a, b) => a.week < b.week ? -1 : 1);
const prev = rows[rows.length - 1] || null;
const LABEL = { deals_created: 'New deals', deals_created_value: 'New deal value', deals_won: 'Deals won', deals_won_value: 'Won value',
  open_pipeline: 'Open pipeline', invoiced: 'Invoiced', payments_received: 'Payments received', unpaid: 'Unpaid invoices', overdue: 'Overdue',
  card_payments: 'Card payments (net)', refunds: 'Refunds', failed_payments: 'Failed card payments' };
const COUNTS = ['deals_created', 'deals_won', 'failed_payments'], lines = [];
for (const [k, label] of Object.entries(LABEL)) {
  if (row[k] === '' || row[k] === undefined) continue;
  const v = Number(row[k]), p = prev && prev[k] !== '' && prev[k] !== undefined ? Number(prev[k]) : null;
  const ch = p === null ? '' : p === 0 ? (v === 0 ? ' (no change)' : ' (new)') : ` (${v >= p ? '+' : ''}${Math.round((v - p) / Math.abs(p) * 100)}% on last week)`;
  lines.push(`${label}: ${COUNTS.includes(k) ? v : v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}${ch}`);
}
if (failed.length) lines.push('', 'Could not read:', ...failed.map(f => '- ' + f));
return [{ json: { row, text: `Week of ${row.week}\n\n` + lines.join('\n'), subject: `${$('Config').first().json.workflow_label}: week of ${row.week}${failed.length ? ' (some sources failed)' : ''}` } }];

// One alert for every failure path. $prevNode names the step that failed.
const cfg = $('Config').first().json;
return $input.all().map(i => {
  const e = i.json.error;
  const msg = String((typeof e === 'string' ? e : e && (e.description || e.message)) || i.json.message || JSON.stringify(i.json)).slice(0, 400);
  return { json: { text: `${cfg.workflow_label}: ${$prevNode.name} failed${i.json.ref ? ' for ' + i.json.ref : ''}. ${msg}` } };
});
